get_price_display_settings.code:
final response = await client.priceDisplaySettings.getPriceDisplaySettings();
final settings = (response.map as Map)['price_display_settings'] as Map;
print(settings['order_item']);
print(settings['order_summary']);

patch_price_display_settings.code:
final response = await client.priceDisplaySettings.patchPriceDisplaySettings({
  'price_display_settings': {
    'order_item': {
      'price_including_tax': {'enabled': true, 'customize': false},
    },
    'order_summary': {
      'payment_surcharge': {'enabled': true, 'customize': false},
    },
  },
});
final settings = (response.map as Map)['price_display_settings'] as Map;
print('${settings['order_item']} ${settings['order_summary']}');

